import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.Aev9KvMf.js";const g=JSON.parse('{"title":"营养标签 2027 新版 · 消费者问答精选","description":"GB 28050-2025 官方问答的消费者精选：千焦与千卡、糖为什么没有 NRV%、哪些食品可以不标营养标签、标示值允许误差。","frontmatter":{"title":"营养标签 2027 新版 · 消费者问答精选","issuer":"国家卫生健康委（标准问答）","source_tier":"一级来源","version":"GB 28050—2025","published":"2025-09","source_url":"https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml","status":"新版已发布（2027-03-16 实施）","tags":["国标","营养标签","消费者问答","行动清单"],"type":"国标科普","reviewed":false,"description":"GB 28050-2025 官方问答的消费者精选：千焦与千卡、糖为什么没有 NRV%、哪些食品可以不标营养标签、标示值允许误差。"},"headers":[],"relativePath":"standards/gb28050-qa-detail.md","filePath":"standards/gb28050-qa-detail.md"}'),o={name:"standards/gb28050-qa-detail.md"};function s(n,t,h,l,c,f){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="营养标签-2027-新版-·-消费者问答精选" tabindex="-1">营养标签 2027 新版 · 消费者问答精选 <a class="header-anchor" href="#营养标签-2027-新版-·-消费者问答精选" aria-label="Permalink to &quot;营养标签 2027 新版 · 消费者问答精选&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据国家卫健委官方问答整理，尚未逐条对照原文校验；校验通过前请以官方问答为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页内容<strong>整理自国家卫健委官方问答</strong>（一级来源），逐条可点击溯源。本站不构成诊疗建议。</p></div><blockquote><p><strong>出处</strong>：<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">《食品安全国家标准 预包装食品营养标签通则》（GB 28050-2025）问答</a>。<strong>2027 年 3 月 16 日实施</strong>。配套阅读：<a href="/SageRelay/standards/gb28050-2025-preview.html">标签要变什么·新旧对比</a>、<a href="/SageRelay/standards/gb28050-nutrition-label.html">GB 28050 词条</a>。</p></blockquote><h2 id="消费者最常问的六件事" tabindex="-1">消费者最常问的六件事 <a class="header-anchor" href="#消费者最常问的六件事" aria-label="Permalink to &quot;消费者最常问的六件事&quot;">​</a></h2><h3 id="_1-能量为什么标的是-千焦" tabindex="-1">1. 能量为什么标的是&quot;千焦&quot;？ <a class="header-anchor" href="#_1-能量为什么标的是-千焦" aria-label="Permalink to &quot;1. 能量为什么标的是&quot;千焦&quot;？&quot;">​</a></h3><p>新版标准规定能量以**千焦（kJ）**为单位标示，由蛋白质、脂肪、碳水等供能成分含量乘以各自换算系数加和得出；标示膳食纤维时按 8kJ/g 计算。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·能量</a>）【本站提示】kJ ÷ 4.184 ≈ 千卡（kcal），习惯&quot;卡路里&quot;的自己换算。</p><h3 id="_2-新版为什么多了-糖-和-饱和脂肪" tabindex="-1">2. 新版为什么多了&quot;糖&quot;和&quot;饱和脂肪&quot;？ <a class="header-anchor" href="#_2-新版为什么多了-糖-和-饱和脂肪" aria-label="Permalink to &quot;2. 新版为什么多了&quot;糖&quot;和&quot;饱和脂肪&quot;？&quot;">​</a></h3><p>强制标示扩展为 <strong>1+6</strong>：能量 + 蛋白质、脂肪、<strong>饱和脂肪（或饱和脂肪酸）</strong>、碳水、<strong>糖</strong>、钠。其中&quot;糖&quot;明确限定为<strong>葡萄糖、果糖、蔗糖、麦芽糖、乳糖之和</strong>。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·强制标示与糖</a>）</p><h3 id="_3-为什么-糖-那一行没有-nrv" tabindex="-1">3. 为什么&quot;糖&quot;那一行没有 NRV%？ <a class="header-anchor" href="#_3-为什么-糖-那一行没有-nrv" aria-label="Permalink to &quot;3. 为什么&quot;糖&quot;那一行没有 NRV%？&quot;">​</a></h3><p>糖没有规定 NRV（营养素参考值），所以它的 NRV% <strong>可以空白、斜线或横线表达</strong>——不是漏印。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·NRV%</a>）</p><h3 id="_4-反式脂肪酸标-0-真的完全没有吗" tabindex="-1">4. 反式脂肪酸标&quot;0&quot;，真的完全没有吗？ <a class="header-anchor" href="#_4-反式脂肪酸标-0-真的完全没有吗" aria-label="Permalink to &quot;4. 反式脂肪酸标&quot;0&quot;，真的完全没有吗？&quot;">​</a></h3><p>若仅天然存在（如乳制品）不要求强制标示，可选择标示；<strong>一旦对反式脂肪酸做声称，就必须强制标示含量</strong>并符合声称要求。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·反式脂肪酸</a>）</p><h3 id="_5-哪些食品可以不标营养标签" tabindex="-1">5. 哪些食品可以不标营养标签？ <a class="header-anchor" href="#_5-哪些食品可以不标营养标签" aria-label="Permalink to &quot;5. 哪些食品可以不标营养标签？&quot;">​</a></h3><p>豁免原则：营养素含量不稳定、包装过小（表面积 ≤40cm²）、食用量小贡献小。<strong>但有例外</strong>：自愿标示、标签含营养信息（如&quot;蛋白质≥3.3%&quot;）、使用营养强化剂或氢化油、有营养声称的，仍须强制标示；腐乳、酱腌菜、酱油、酱类、复合调味料等高钠食品应当标示；茶叶可豁免；酒精度 &gt;0.5%vol 的饮料酒可不标。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·豁免</a>）</p><h3 id="_6-标示值可信吗-会不会虚标" tabindex="-1">6. 标示值可信吗，会不会虚标？ <a class="header-anchor" href="#_6-标示值可信吗-会不会虚标" aria-label="Permalink to &quot;6. 标示值可信吗，会不会虚标？&quot;">​</a></h3><p>标示值应真实反映含量，标准设有<strong>允许误差</strong>判定；但产品是否合格还要结合相应产品标准的营养质量要求（如灭菌乳蛋白质应 ≥2.9g/100g，两者同时满足）。（<a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·允许误差</a>）</p><h2 id="附录-·-其他值得知道的细节" tabindex="-1">附录 · 其他值得知道的细节 <a class="header-anchor" href="#附录-·-其他值得知道的细节" aria-label="Permalink to &quot;附录 · 其他值得知道的细节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>细节</th><th>要点</th><th>出处</th></tr></thead><tbody><tr><td>碳水怎么算</td><td>总碳水 = 100 −（蛋白质+脂肪+水分+灰分）；标了膳食纤维再减去即&quot;可利用碳水&quot;</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·碳水</a></td></tr><tr><td>营养强化剂</td><td>按 GB 14880 作强化剂使用时须标含量及 NRV%；仅作添加剂可不满标</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·强化剂</a></td></tr><tr><td>n-3 脂肪酸声称</td><td>α-亚麻酸、DHA、EPA 含量符合附录 C 条件可声称&quot;富含 n-3&quot;</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·声称</a></td></tr><tr><td>格式</td><td>附录 B 推荐 8 种基本格式；可横排、可文字格式（小包装）</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">问答·格式</a></td></tr></tbody></table><h2 id="原文与溯源" tabindex="-1">原文与溯源 <a class="header-anchor" href="#原文与溯源" aria-label="Permalink to &quot;原文与溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>版本</td><td>GB 28050—2025（2027-03-16 实施）</td></tr><tr><td>归口</td><td>国家卫生健康委（食品安全国家标准）</td></tr><tr><td>出处</td><td><a href="https://www.nhc.gov.cn/sps/c100087/202509/470fa4ff5de14dd38619223cce9da4e7.shtml" target="_blank" rel="noreferrer">官方问答页</a> · <a href="https://openstd.samr.gov.cn/bzgk/gb/std_list?p.p2=28050" target="_blank" rel="noreferrer">标准查询（全文公开系统）</a></td></tr></tbody></table>',21)])])}const u=a(o,[["render",s]]);export{g as __pageData,u as default};
